mkdir -p /app/bs && cat > /app/bs/bs.py <<'EOF'
import numpy as np, itertools, json, sys, os
N=6
def places(L):
    out=[]
    for r in range(N):
        for c in range(N):
            if c+L<=N: out.append((0,tuple((r,c+i) for i in range(L))))
            if r+L<=N: out.append((1,tuple((r+i,c) for i in range(L))))
    return out
P=[places(4),places(3),places(2)]
def nb(cells):
    s=set()
    for r,c in cells:
        for dr in(-1,0,1):
            for dc in(-1,0,1): s.add((r+dr,c+dc))
    return s
cache='/app/bs/lay.npz'
if os.path.exists(cache):
    d=np.load(cache); occ=d['occ']; sat=d['sat']
else:
    occs=[];sats=[]
    for a in P[0]:
        for b in P[1]:
            if set(a[1])&set(b[1]): continue
            for c in P[2]:
                if (set(a[1])|set(b[1]))&set(c[1]): continue
                sh=[a,b,c]; o=np.zeros(36,bool)
                for s in sh:
                    for (r,cc) in s[1]: o[r*6+cc]=1
                touch=lambda x,y: bool(nb(x[1])&set(y[1]))
                nt=not any(touch(sh[i],sh[j]) for i in range(3) for j in range(i+1,3))
                par=len({s[0] for s in sh})==1
                bor=all(any(r in(0,5) or cc in(0,5) for r,cc in s[1]) for s in sh)
                cc_=not any(o[r*6+k] for r in(2,3) for k in(2,3))
                cl=all(any(touch(sh[i],sh[j]) for j in range(3) if j!=i) for i in range(3))
                occs.append(o); sats.append([1,nt,par,bor,cc_,cl])
    occ=np.array(occs); sat=np.array(sats,bool); np.savez(cache,occ=occ,sat=sat)
names=["any","no_touch","parallel","border","center_clear","clustered"]
Nr=sat.sum(0); print(Nr,file=sys.stderr)
W=sat/Nr  # P(layout|rule)
obs=json.load(open('/app/bs/obs.json')) if os.path.exists('/app/bs/obs.json') else []
rowc=occ.reshape(-1,6,6).sum(2); colc=occ.reshape(-1,6,6).sum(1)
def lik_scan(true,rep):
    l=np.where(true==rep,0.7,0.0)+np.where(np.abs(true-rep)==1,0.15,0.0)
    if rep==0: l=l+np.where(true==0,0.15,0)
    if rep==6: l=l+np.where(true==6,0.15,0)
    return l
def lik(o):
    if o[0]=='fire':
        _,r,c,v=o; h=occ[:,r*6+c]
        return np.where(h==v,0.9,0.1)
    _,ax,i,v=o; t=(rowc if ax=='row' else colc)[:,i]
    return lik_scan(t,v)
L=np.ones(len(occ))
for o in obs: L*=lik(o)
J=W*L[:,None]  # joint layout x rule
def score_of(J):
    Z=J.sum(); pr=J.sum(0)/Z; pl=J.sum(1)/Z; m=pl@occ
    return pr,m
def ent(pr,m):
    m=np.clip(m,1e-12,1-1e-12); pr=np.clip(pr,1e-12,1)
    return -(pr*np.log(pr)).sum()/np.log(6)+(-(m*np.log(m)+(1-m)*np.log(1-m))).sum()/20.1236
pr,m=score_of(J)
print("rules",dict(zip(names,np.round(pr,3))))
print(np.round(m.reshape(6,6),2))
if len(sys.argv)>1 and sys.argv[1]=='plan':
    H0=ent(pr,m); res=[]
    acts=[('fire',r,c) for r in range(6) for c in range(6)]+[('scan',a,i) for a in('row','col') for i in range(6)]
    for a in acts:
        outs=[0,1] if a[0]=='fire' else range(7)
        EH=0
        for v in outs:
            Jv=J*lik(a+(v,))[:,None]; p=Jv.sum()/J.sum()
            if p<1e-9: continue
            EH+=p*ent(*score_of(Jv))
        cost=1 if a[0]=='fire' else 2
        res.append(((H0-EH)/cost,H0-EH,a))
    res.sort(reverse=True)
    for x in res[:8]: print(x)
EOF
cd /app/bs && python3 bs.py plan

